{"explanation":"An inscribed angle is half the central angle that subtends the same chord. Here A and B stay fixed, so the central angle remains 120° and the inscribed angle at P remains 60° as you drag P along the opposite arc. The drag is limited to that arc because moving P across chord AB would produce a different angle.","manimCode":"const center = [-1.6, 0, 0];
const radius = 2.35;
const aAngle = 7 * Math.PI / 6;
const bAngle = -Math.PI / 6;
const pointAt = angle => [center[0] + radius * Math.cos(angle), center[1] + radius * Math.sin(angle), 0];
const A = pointAt(aAngle);
const B = pointAt(bAngle);

const title = new Text({ text: 'Inscribed angle theorem', color: WHITE, fontSize: 36 });
title.moveTo([0, 3.3, 0]);

const circle = new Circle({ radius, color: BLUE });
circle.moveTo(center);
circle.setStrokeWidth(3);

const chord = new Line({ start: A, end: B, color: TEAL });
chord.setStrokeWidth(4);

const centralRayA = new Line({ start: center, end: A, color: GRAY });
const centralRayB = new Line({ start: center, end: B, color: GRAY });

const centralWedgePoints = [center];
for (let i = 0; i <= 20; i++) {
  const angle = -5 * Math.PI / 6 + i * (2 * Math.PI / 3) / 20;
  centralWedgePoints.push([center[0] + 0.58 * Math.cos(angle), center[1] + 0.58 * Math.sin(angle), 0]);
}
const centralWedge = new Polygon({ vertices: centralWedgePoints, color: ORANGE });
centralWedge.setFill(ORANGE, 0.25);
centralWedge.setStrokeWidth(2);

let theta = Math.PI / 2;
const P = new Dot({ point: pointAt(theta), color: YELLOW });
const dotA = new Dot({ point: A, color: TEAL });
const dotB = new Dot({ point: B, color: TEAL });
const O = new Dot({ point: center, color: ORANGE });

const rayA = new Polygon({ vertices: [pointAt(theta), A], color: YELLOW });
const rayB = new Polygon({ vertices: [pointAt(theta), B], color: YELLOW });
rayA.setFillOpacity(0).setStrokeWidth(3);
rayB.setFillOpacity(0).setStrokeWidth(3);

const angleWedge = new Polygon({ vertices: [pointAt(theta), pointAt(theta)], color: YELLOW });
angleWedge.setFill(YELLOW, 0.3);
angleWedge.setStrokeWidth(2);

function updateInscribedAngle() {
  const p = P.getCenter();
  rayA.setVertices([p, A]);
  rayB.setVertices([p, B]);
  const start = Math.atan2(A[1] - p[1], A[0] - p[0]);
  const end = Math.atan2(B[1] - p[1], B[0] - p[0]);
  let sweep = end - start;
  while (sweep > Math.PI) sweep -= 2 * Math.PI;
  while (sweep < -Math.PI) sweep += 2 * Math.PI;
  const vertices = [p];
  for (let i = 0; i <= 14; i++) {
    const angle = start + sweep * i / 14;
    vertices.push([p[0] + 0.45 * Math.cos(angle), p[1] + 0.45 * Math.sin(angle), 0]);
  }
  angleWedge.setVertices(vertices);
}
updateInscribedAngle();

const labelA = new Text({ text: 'A', color: TEAL, fontSize: 24 });
labelA.moveTo([A[0] - 0.3, A[1] - 0.2, 0]);
const labelB = new Text({ text: 'B', color: TEAL, fontSize: 24 });
labelB.moveTo([B[0] + 0.3, B[1] - 0.2, 0]);
const labelP = new Text({ text: 'P', color: YELLOW, fontSize: 24 });
labelP.addUpdater(() => {
  const p = P.getCenter();
  const dx = (p[0] - center[0]) / radius;
  const dy = (p[1] - center[1]) / radius;
  labelP.moveTo([p[0] + 0.3 * dx, p[1] + 0.3 * dy, 0]);
});

const centralText = new Text({ text: '120°', color: ORANGE, fontSize: 25 });
centralText.moveTo([-1.6, -0.77, 0]);
const angleText = new Text({ text: '60°', color: YELLOW, fontSize: 31 });
angleText.moveTo([3.65, 0.65, 0]);
const formula = new Text({ text: 'Inscribed angle = ½ × central angle', color: WHITE, fontSize: 24 });
formula.moveTo([3.65, 1.45, 0]);
const instruction = new Text({ text: 'Drag P along the opposite arc', color: BLUE, fontSize: 22 });
instruction.moveTo([3.65, -0.65, 0]);

await scene.play(new Write(title));
await scene.play(new AnimationGroup([new Create(circle), new Create(chord)]));
scene.add(centralWedge, centralRayA, centralRayB, O, dotA, dotB, labelA, labelB, centralText);
scene.add(angleWedge, rayA, rayB, P, labelP, formula, angleText, instruction);

makeDraggable(P, scene, {
  onDrag: (mob, pos) => {
    const x = pos[0] - center[0];
    const y = pos[1] - center[1];
    const raw = Math.atan2(y, x);
    const candidates = [raw - 2 * Math.PI, raw, raw + 2 * Math.PI];
    let nearest = candidates[0];
    for (const candidate of candidates) {
      if (Math.abs(candidate - theta) < Math.abs(nearest - theta)) nearest = candidate;
    }
    theta = Math.max(bAngle + 0.12, Math.min(aAngle - 0.12, nearest));
    mob.moveTo(pointAt(theta));
    updateInscribedAngle();
  }
});

await scene.wait(999999);"}

